  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-1419', 'Human physiology', 'Control of heartbeat', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 236 (§11.1)', 'The delay of about 0.15 s between the SA node and AV node allows', '["atrial systole to finish before ventricular systole begins", "the ventricles to contract first", "the semilunar valves to open", "the heart to rest for a full minute"]', 0, 'The delay lets atrial contraction be completed before ventricular systole starts.', '{"1": "Atria contract first.", "2": "Not the purpose.", "3": "Not the purpose."}'),
  ('BIO-1420', 'Human physiology', 'Control of heartbeat', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 236 (§11.1)', 'An artificial pacemaker is used in patients with', '["a leaky mitral valve only", "high cholesterol", "a blocked coronary artery", "a weak SA node"]', 3, 'In patients with a weak SA node, a battery-operated pacemaker implanted near the AV node triggers normal beats.', '{"0": "Valve defects are treated by valve replacement.", "1": "Not the indication.", "2": "Blocked arteries are treated by bypass or angioplasty."}'),
  ('BIO-1421', 'Human physiology', 'Control of heartbeat', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 237 (§11.1)', 'During fever or exercise, heart rate rises because', '["the heart stops receiving blood", "the SA node is removed", "a brain control centre sends signals to the SA and AV nodes", "Purkinje fibres slow down"]', 2, 'The brain''s control centre signals the pacemaker and AV node to increase the rate during fever and exercise and slows them at rest.', '{"0": "Not the cause.", "1": "Not the cause.", "3": "Not the cause."}'),
  ('BIO-1422', 'Human physiology', 'Control of heartbeat', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 237 (§11.1)', 'The heart of an average adult beats about', '["40 times per minute", "70 times per minute", "120 times per minute", "200 times per minute"]', 1, 'An average adult heart beats about 70 times a minute, pumping the whole blood volume (about 5 L) each minute.', '{"0": "Too slow.", "2": "Too fast at rest.", "3": "Far too fast."}'),
  ('BIO-1423', 'Human physiology', 'ECG', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 238 (§11.1)', 'The P wave of an ECG represents', '["atrial depolarization initiated by the SA node", "ventricular depolarization", "ventricular repolarization", "closure of semilunar valves"]', 0, 'The P wave shows the start of atrial depolarization by the SA node, causing atrial contraction.', '{"1": "That is the QRS complex.", "2": "That is the T wave.", "3": "ECG records electrical, not valve, events."}'),
  ('BIO-1424', 'Human physiology', 'ECG', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 238 (§11.1)', 'A prolonged PR segment on an ECG indicates', '["myocardial infarction", "first-degree heart block", "electrolyte disturbance", "ventricular tachycardia"]', 1, 'PR is normally 0.12–0.20 s; a prolonged PR indicates first-degree heart block.', '{"0": "Infarction elevates ST.", "2": "T-wave abnormalities may indicate electrolyte disturbance.", "3": "QRS abnormalities may show tachycardia."}'),
  ('BIO-1425', 'Human physiology', 'ECG', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 238 (§11.1)', 'The ST segment may be depressed in', '["first-degree heart block", "a normal heart at rest", "ischemia", "arrhythmia shown by absent P waves"]', 2, 'The ST segment can be depressed in ischemia and elevated in myocardial infarction.', '{"0": "That prolongs PR.", "1": "It is not depressed normally.", "3": "Absent P waves show arrhythmia."}'),
  ('BIO-1426', 'Human physiology', 'ECG', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 238 (§11.1)', 'The T wave represents', '["the beginning of ventricular repolarization", "atrial depolarization", "atrial repolarization", "ventricular depolarization"]', 0, 'The T wave represents the start of ventricular repolarization.', '{"1": "That is the P wave.", "2": "Atrial repolarization occurs during QRS.", "3": "That is QRS."}'),
  ('BIO-1427', 'Human physiology', 'ECG', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 238 (§11.1)', 'Blue babies have cyanosis because', '["the SA node is missing", "the lungs have no alveoli", "the heart has only three chambers", "the interatrial foramen or ductus arteriosus fails to close, mixing blood"]', 3, 'Failure of the interatrial foramen to close, or of the ductus arteriosus to constrict, mixes oxygenated and deoxygenated blood.', '{"0": "Not the cause.", "1": "Not the cause.", "2": "Not the cause."}'),
  ('BIO-1428', 'Human physiology', 'Blood vessels', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 239 (§11.2)', 'In arteries, the layer that withstands high pressure during ventricular systole is the', '["tunica intima of endothelium", "tunica media of thick muscle and elastic fibres", "tunica externa of connective tissue", "lumen"]', 1, 'The middle layer, tunica media, of thick muscle and elastic fibres withstands high blood pressure.', '{"0": "The intima is a thin endothelium.", "2": "The externa is connective tissue.", "3": "The lumen is the space."}'),
  ('BIO-1429', 'Human physiology', 'Blood vessels', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 239 (§11.2)', 'Which artery carries deoxygenated blood?', '["Aorta", "Coronary artery", "Renal artery", "Pulmonary artery"]', 3, 'All arteries carry oxygenated blood except the pulmonary arteries.', '{"0": "The aorta carries oxygenated blood.", "1": "Coronary arteries carry oxygenated blood.", "2": "Renal arteries carry oxygenated blood."}'),
  ('BIO-1430', 'Human physiology', 'Blood vessels', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 239 (§11.2)', 'The internal diameter of a capillary is about', '["8 millimetres", "0.1 micrometre", "8 micrometres", "100 micrometres"]', 2, 'Capillaries are about 8 µm across, so RBCs pass in single file; no cell is more than 100 µm from a capillary.', '{"0": "Far too large.", "1": "0.1 µm is alveolar epithelium thickness.", "3": "100 µm is the maximum distance from a capillary."}'),
  ('BIO-1431', 'Human physiology', 'Blood vessels', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 239 (§11.2)', 'Capillary walls are made of', '["three layers like arteries", "a single layer of endothelial cells", "smooth muscle and elastic fibres", "cartilage"]', 1, 'Capillary walls are a single layer of endothelial cells, allowing exchange.', '{"0": "Arteries and veins have three layers.", "2": "Those are in the tunica media.", "3": "Not present."}'),
  ('BIO-1432', 'Human physiology', 'Blood vessels', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 240 (§11.2)', 'Which component of blood normally remains inside capillaries?', '["Large proteins", "Water", "Dissolved gases", "Small nutrients"]', 0, 'Fluid leaking into tissues carries water, nutrients, hormones, gases, wastes and small proteins; large proteins, RBCs and platelets stay in.', '{"1": "Water leaks out.", "2": "Gases leave.", "3": "Nutrients leave."}'),
  ('BIO-1433', 'Human physiology', 'Blood vessels', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 240 (§11.2)', 'An empty vein collapses while an empty artery stays a hollow tube because the vein''s', '["wall has no endothelium", "lumen is smaller", "valves hold it shut", "tunica media is thin with little muscle and few elastic fibres"]', 3, 'The middle layer of veins is thin and slightly muscular because veins do not withstand high pressure.', '{"0": "Veins have an endothelium.", "1": "Not the reason.", "2": "Valves stop backflow, not collapse."}'),
  ('BIO-1434', 'Human physiology', 'Blood vessels', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 240 (§11.2)', 'Return of venous blood to the heart is helped by', '["valves in veins and contraction of surrounding muscles", "high pressure from the left ventricle", "precapillary sphincters", "the SA node"]', 0, 'Semilunar valves in veins prevent backflow and contraction of surrounding muscles presses veins.', '{"1": "Pressure is low in veins.", "2": "Those control capillary flow.", "3": "Not involved."}'),
  ('BIO-1435', 'Human physiology', 'Blood vessels', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 241 (§11.2)', 'The amount of blood entering a capillary loop is regulated by', '["semilunar valves", "precapillary sphincters", "the AV node", "lymph nodes"]', 1, 'Rings of muscle called precapillary sphincters guard each capillary loop and regulate flow.', '{"0": "Those are in veins and arteries.", "2": "Not involved.", "3": "Not involved."}'),
  ('BIO-1436', 'Human physiology', 'Blood vessels', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 241 (§11.2)', 'Which chemical can dilate capillaries?', '["Antidiuretic hormone", "Calcium", "Histamine", "Fibrin"]', 2, 'Nervous stimulation constricts capillaries and chemicals such as histamine dilate them.', '{"0": "ADH constricts arterioles.", "1": "Not named.", "3": "Fibrin forms clots."}'),
  ('BIO-1437', 'Human physiology', 'Blood vessels', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 241 (§11.2)', 'When the metabolic activity of a tissue rises, its arterioles', '["constrict, reducing blood flow", "dilate as their circular muscles relax, increasing blood flow", "close completely", "are unaffected"]', 1, 'Falling O2 and rising CO2 in the tissue fluid relax arteriolar circular muscle (vasodilation), increasing flow.', '{"0": "Constriction follows decreased activity.", "2": "Not described.", "3": "They respond."}'),
  ('BIO-1438', 'Human physiology', 'Blood vessels', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 241 (§11.2)', 'Blood velocity is lowest in', '["the aorta", "the venae cavae", "capillaries, at about 1 mm/s", "arterioles"]', 2, 'Velocity is highest in the aorta (450–500 mm/s), lowest in capillaries (about 1 mm/s), and rises again in veins (250–300 mm/s).', '{"0": "The aorta is fastest.", "1": "Velocity rises again in venae cavae.", "3": "Arterioles are faster than capillaries."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-1439', 'Human physiology', 'Blood vessels', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 242 (§11.2)', 'Blood velocity changes along the vascular system mainly because of changes in', '["the total cross-sectional area of the vessels", "the colour of blood", "the number of red cells", "the thickness of the endothelium only"]', 0, 'Changes in velocity result from changes in the total cross-section of the vessel system.', '{"1": "Not a cause.", "2": "Not the reason given.", "3": "Not the reason given."}'),
  ('BIO-1440', 'Human physiology', 'Circulatory pathways', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 243 (§11.2)', 'Most coronary veins drain into the right atrium through the', '["pulmonary veins", "superior vena cava", "hepatic portal vein", "coronary sinus"]', 3, 'Coronary veins join to form the coronary sinus, which opens into the right atrium.', '{"0": "Pulmonary veins enter the left atrium.", "1": "Not described.", "2": "The portal vein goes to the liver."}'),
  ('BIO-1441', 'Human physiology', 'Circulatory pathways', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 243 (§11.2)', 'The coronary arteries arise from the', '["pulmonary trunk", "right atrium", "aorta near its origin", "inferior vena cava"]', 2, 'Right and left coronary arteries arise from the aorta near its origin.', '{"0": "The pulmonary trunk goes to the lungs.", "1": "The atrium is a chamber.", "3": "A vein cannot supply them."}'),
  ('BIO-1442', 'Human physiology', 'Circulatory pathways', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 244 (§11.2)', 'A portal system is a circulation in which', '["arteries open directly into veins", "blood flows only to the lungs", "capillaries are absent", "veins end in capillaries"]', 3, 'In a portal system veins end in capillaries; the hepatic portal vein carries blood from gut and spleen to liver capillaries.', '{"0": "Not the definition.", "1": "That is pulmonary circulation.", "2": "Capillaries are present."}'),
  ('BIO-1443', 'Human physiology', 'Circulatory pathways', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 244 (§11.2)', 'The hepatic portal vein collects blood from the', '["alimentary canal and spleen", "kidneys", "lungs", "brain"]', 0, 'It collects blood from the spleen and alimentary canal and takes it to the liver.', '{"1": "Kidneys drain via renal veins.", "2": "Lungs drain via pulmonary veins.", "3": "Not involved."}'),
  ('BIO-1444', 'Human physiology', 'Circulatory pathways', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 244 (§11.2)', 'In the renal circulation, the efferent arteriole divides into', '["glomerular capillaries only", "peritubular capillaries and vasa recta", "the renal vein", "afferent arterioles"]', 1, 'Afferent arterioles form glomeruli; the efferent arteriole divides into peritubular capillaries (cortex) and vasa recta (medulla).', '{"0": "Glomeruli come from afferent arterioles.", "2": "The renal vein forms later.", "3": "Afferent arterioles come before."}'),
  ('BIO-1445', 'Human physiology', 'Blood pressure', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 245 (§11.3)', 'Normal diastolic pressure in a young adult is about', '["40 mm Hg", "80 mm Hg", "120 mm Hg", "140 mm Hg"]', 1, 'Systolic pressure is about 120 mm Hg and diastolic about 80 mm Hg (120/80).', '{"0": "Too low.", "2": "120 mm Hg is systolic.", "3": "140 is a hypertension threshold."}'),
  ('BIO-1446', 'Human physiology', 'Blood pressure', 'easy', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 246 (§11.3)', 'The instrument used for manual measurement of blood pressure is the', '["sphygmomanometer", "electrocardiograph", "stethoscope only", "angiograph"]', 0, 'A sphygmomanometer measures systolic and diastolic pressures by a mercury column.', '{"1": "It records ECG.", "2": "A stethoscope hears heart sounds.", "3": "Angiography is an X-ray method."}'),
  ('BIO-1447', 'Human physiology', 'Blood pressure', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 246 (§11.3)', 'Baroreceptors that detect blood pressure are located in the', '["right atrium only", "carotid arteries and aortic arch", "kidneys", "pulmonary veins"]', 1, 'Pressure receptors (baroreceptors) are in the carotid arteries and aortic arch.', '{"0": "The right atrium secretes ANH.", "2": "Kidneys respond to ADH.", "3": "Not described."}'),
  ('BIO-1448', 'Human physiology', 'Blood pressure', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 246 (§11.3)', 'When blood pressure falls, the brain responds through baroreceptors by', '["slowing the heart", "dilating arterioles", "increasing heart rate and force and constricting arterioles", "secreting ANH"]', 2, 'The control centre increases the rate and force of heart contraction and causes vasoconstriction, restoring pressure.', '{"0": "That lowers pressure.", "1": "That lowers pressure.", "3": "ANH lowers pressure."}'),
  ('BIO-1449', 'Human physiology', 'Blood pressure', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 246 (§11.3)', 'Atrial natriuretic hormone (ANH) is secreted when', '["blood volume falls", "the person is thirsty", "the SA node is weak", "the right atrium is stretched by increased blood volume"]', 3, 'Stretching of the right atrium by high blood volume releases ANH, which increases salt and water excretion and lowers pressure.', '{"0": "Low volume triggers ADH and thirst.", "1": "Thirst is linked to low volume.", "2": "Not related."}'),
  ('BIO-1450', 'Human physiology', 'Blood pressure', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 246 (§11.3)', 'Antidiuretic hormone raises blood pressure by', '["increasing salt excretion", "making kidneys retain water and constricting arterioles", "dilating arterioles", "slowing the heart"]', 1, 'ADH from the posterior pituitary makes kidneys retain water and also constricts arterioles.', '{"0": "That is ANH.", "2": "It constricts arterioles.", "3": "Not its action."}'),
  ('BIO-1451', 'Human physiology', 'Cardiovascular disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 247 (§11.4)', 'The prime contributor to atherosclerosis is thought to be accumulation of', '["calcium", "glucose", "haemoglobin", "cholesterol"]', 3, 'Various materials deposit in arteries, but cholesterol accumulation is thought to be the prime contributor.', '{"0": "Calcium hardens walls in arteriosclerosis.", "1": "Not named.", "2": "Not named."}'),
  ('BIO-1452', 'Human physiology', 'Cardiovascular disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 247 (§11.4)', 'Arteriosclerosis is hardening of arterial walls due to deposition of', '["cholesterol only", "fibrin only", "calcium", "lymph"]', 2, 'Arteriosclerosis occurs when calcium is deposited in arterial walls; severe atherosclerosis usually leads to it.', '{"0": "Cholesterol causes atherosclerosis.", "1": "Fibrin forms clots.", "3": "Not described."}'),
  ('BIO-1453', 'Human physiology', 'Cardiovascular disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 247 (§11.4)', 'In coronary angiography, the coronary arteries are made visible on X-ray by', '["injecting a contrast dye through a catheter", "inflating a balloon", "placing electrodes on the chest", "listening with a stethoscope"]', 0, 'A catheter is guided to the coronary arteries and a contrast medium is injected, producing angiograms.', '{"1": "That is angioplasty.", "2": "That is ECG.", "3": "That hears heart sounds."}'),
  ('BIO-1454', 'Human physiology', 'Cardiovascular disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 248 (§11.4)', 'A thrombus that is dislodged and carried to another site is called an', '["aneurysm", "embolus", "angina", "infarct"]', 1, 'A dislodged thrombus carried elsewhere in the circulation is an embolus.', '{"0": "Not described.", "2": "Angina is chest pain.", "3": "Infarction is tissue death."}'),
  ('BIO-1455', 'Human physiology', 'Cardiovascular disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 247 (§11.4)', 'Thrombus formation can be caused by', '["high histamine levels", "a strong SA node", "lymph node swelling", "reduced blood flow during long periods of inactivity"]', 3, 'Causes include irritation or infection of vessel lining, reduced flow from inactivity, and diseases like pneumonia or TB.', '{"0": "Not named.", "1": "Not a cause.", "2": "Not a cause."}'),
  ('BIO-1456', 'Human physiology', 'Cardiovascular disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 248 (§11.4)', 'Angina pectoris is', '["chest pain during exertion showing that the heart''s oxygen demand exceeds supply", "death of heart muscle", "rupture of a brain vessel", "a hissing heart sound"]', 0, 'Angina is chest pain during stress or exertion from narrowed coronary arteries, warning of possible heart attack.', '{"1": "That is myocardial infarction.", "2": "That is brain haemorrhage.", "3": "That is a murmur."}'),
  ('BIO-1457', 'Human physiology', 'Cardiovascular disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 248 (§11.4)', 'In coronary bypass surgery,', '["a balloon dilates the blocked artery", "a stent is inserted", "a healthy vessel from the patient is attached above and below the blocked artery", "the heart is replaced"]', 2, 'A vessel from the leg, arm, chest or abdomen is attached around the blockage, bypassing it.', '{"0": "That is angioplasty.", "1": "That is stenting.", "3": "Not bypass."}'),
  ('BIO-1458', 'Human physiology', 'Cardiovascular disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 249 (§11.4)', 'A stent is', '["a dye seen on X-rays", "an expandable stainless steel mesh tube that keeps an artery open", "a vessel taken from the leg", "a battery-operated device near the AV node"]', 1, 'A stent mounted on a balloon catheter is expanded in the narrowed artery and left to support its walls.', '{"0": "That is a contrast medium.", "2": "That is a bypass graft.", "3": "That is an artificial pacemaker."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-1459', 'Human physiology', 'Cardiovascular disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 249 (§11.4)', 'Hypertension is a blood pressure that consistently remains above', '["120/80 mm Hg", "100/60 mm Hg", "90/60 mm Hg", "140/90 mm Hg"]', 3, 'Hypertension is chronic elevation of blood pressure, consistently above 140/90.', '{"0": "120/80 is normal.", "1": "Below normal.", "2": "Below normal."}'),
  ('BIO-1460', 'Human physiology', 'Cardiovascular disorders', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 249 (§11.4)', 'Prolonged hypertension can cause congestive heart failure, in which', '["the heart cannot pump effectively and blood is retained in the heart and lungs", "a coronary artery is suddenly blocked by a clot", "a brain vessel ruptures", "the SA node stops firing"]', 0, 'Hypertension weakens cardiac muscle; the heart cannot maintain flow and blood is retained in the heart and lungs.', '{"1": "That is heart attack.", "2": "That is brain haemorrhage.", "3": "Not described."}'),
  ('BIO-1461', 'Human physiology', 'Lymphatic system', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 250 (§11.5)', 'Interstitial fluid becomes lymph when it', '["leaves blood capillaries", "enters the right atrium", "enters lymph capillaries", "is filtered in the kidney"]', 2, 'Interstitial fluid forced into blind-ended lymph capillaries is called lymph.', '{"0": "Leaving capillaries makes interstitial fluid.", "1": "Lymph joins veins before the heart.", "3": "Not related."}'),
  ('BIO-1462', 'Human physiology', 'Lymphatic system', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 250 (§11.5)', 'Larger molecules can enter lymph capillaries because they are', '["less permeable than blood capillaries", "connected to arteries", "more permeable than blood capillaries", "lined with cartilage"]', 2, 'Lymph capillaries are more permeable than blood capillaries, so larger molecules can enter.', '{"0": "They are more permeable.", "1": "They begin blind in tissue fluid.", "3": "Not present."}'),
  ('BIO-1463', 'Human physiology', 'Lymphatic system', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 250 (§11.5)', 'The thoracic duct empties lymph into the', '["right subclavian vein", "left subclavian vein", "inferior vena cava", "right atrium"]', 1, 'The right lymphatic duct opens into the right subclavian vein and the thoracic duct into the left subclavian vein.', '{"0": "That receives the right lymphatic duct.", "2": "Not described.", "3": "Not directly."}'),
  ('BIO-1464', 'Human physiology', 'Lymphatic system', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 250 (§11.5)', 'Flow of lymph towards the thoracic duct is maintained by', '["skeletal muscle activity, movement of viscera and breathing", "a lymph heart", "the SA node", "high arterial pressure in lymph vessels"]', 0, 'Lymph flow is maintained by skeletal muscles, visceral movements and breathing; valves prevent backflow.', '{"1": "Humans have no lymph heart.", "2": "Not involved.", "3": "Lymph vessels are not arteries."}'),
  ('BIO-1465', 'Human physiology', 'Lymphatic system', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 251 (§11.5)', 'Each day about how much extra fluid leaving blood capillaries is returned by the lymphatic system?', '["Fifty millilitres", "Eight thousand litres", "Five litres per minute", "Three litres"]', 3, 'About three litres more fluid leaves blood capillaries daily and is returned by lymphatics.', '{"0": "50 mL is pericardial fluid.", "1": "8,000 L is daily blood flow.", "2": "5 L/min is cardiac output."}'),
  ('BIO-1466', 'Human physiology', 'Lymphatic system', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 251 (§11.5)', 'Besides filtering blood, the spleen', '["destroys aged red blood cells and stores RBCs", "produces bile", "secretes ADH", "pumps lymph"]', 0, 'The spleen''s macrophages and lymphocytes destroy foreign particles and aged RBCs; it also stores RBCs.', '{"1": "Bile is from the liver.", "2": "ADH is from the posterior pituitary.", "3": "Not its role."}'),
  ('BIO-1467', 'Human physiology', 'Lymphatic system', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 252 (§11.5)', 'A lymph node receives lymph through', '["one afferent and several efferent vessels", "arteries and veins only", "several afferent vessels and drains it by a single efferent vessel", "the thoracic duct directly"]', 2, 'Several afferent lymph vessels enter a node and one efferent vessel drains it.', '{"0": "Reversed.", "1": "Lymph vessels, not blood vessels.", "3": "Not described."}'),
  ('BIO-1468', 'Human physiology', 'Lymphatic system', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human Circulatory System, p. 252 (§11.5)', 'Which of these is a larger lymphoid mass that produces lymphocytes?', '["Pancreas", "Thymus", "Liver", "Thyroid"]', 1, 'The larger lymphoid masses are the spleen, thymus, tonsils and adenoids, which produce lymphocytes.', '{"0": "The pancreas is a digestive and endocrine gland.", "2": "Not listed.", "3": "Not listed."}'),
  ('BIO-1469', 'Human physiology', 'Bone', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 255 (§12.1)', 'The tough membrane covering the surface of a bone is the', '["perichondrium", "sarcolemma", "periosteum", "synovial membrane"]', 2, 'A bone''s surface is covered by a tough membrane called the periosteum; cartilage is covered by perichondrium.', '{"0": "Perichondrium surrounds cartilage.", "1": "Sarcolemma is a muscle fibre membrane.", "3": "Synovial membrane lines joint capsules."}'),
  ('BIO-1470', 'Human physiology', 'Bone', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 255 (§12.1)', 'The shaft of a long bone is called the', '["diaphysis", "epiphysis", "acetabulum", "lacuna"]', 0, 'The ends of a long bone are epiphyses and the shaft is the diaphysis.', '{"1": "The epiphyses are the ends.", "2": "The acetabulum is the hip socket.", "3": "Lacunae hold osteocytes."}'),
  ('BIO-1471', 'Human physiology', 'Bone', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 256 (§12.1)', 'The basic structural units of compact bone are', '["sarcomeres", "trabeculae of cartilage", "myofibrils", "Haversian systems"]', 3, 'Compact bone is built of Haversian systems of lamellae, lacunae with osteocytes, and a central Haversian canal.', '{"0": "Sarcomeres are muscle units.", "1": "Not the term used.", "2": "Myofibrils are in muscle fibres."}'),
  ('BIO-1472', 'Human physiology', 'Bone', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 256 (§12.1)', 'Bone is both strong and flexible because its matrix contains', '["only collagen", "rigid calcium phosphate crystals and flexible collagen fibres", "only calcium carbonate", "elastin and proteoglycans only"]', 1, 'Brittle but rigid calcium phosphate crystals give strength while flexible collagen gives flexibility.', '{"0": "Collagen alone is weak.", "2": "The crystals are calcium phosphate.", "3": "That describes cartilage matrix."}'),
  ('BIO-1473', 'Human physiology', 'Bone', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 256 (§12.1)', 'In compact bone, osteocytes are connected to each other and to the Haversian canal by', '["T-tubules", "lacteals", "plasmodesmata", "canaliculi"]', 3, 'Osteocytes in lacunae are linked by small channels called canaliculi.', '{"0": "T-tubules are in muscle fibres.", "1": "Lacteals are in villi.", "2": "Plasmodesmata are in plants."}'),
  ('BIO-1474', 'Human physiology', 'Bone', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 256 (§12.1)', 'The Haversian canal contains', '["blood vessels, nerves and lymphatic vessels", "bone marrow only", "synovial fluid", "chondrocytes"]', 0, 'The central Haversian canal contains blood vessels, nerves and lymphatics.', '{"1": "Marrow fills cavities, not Haversian canals.", "2": "Synovial fluid is in joints.", "3": "Chondrocytes are cartilage cells."}'),
  ('BIO-1475', 'Human physiology', 'Bone', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 256 (§12.1)', 'Red bone marrow is found in', '["only the shafts of long bones", "cartilage of the ear", "spongy bone, ribs, vertebrae, sternum and pelvis", "the Haversian canals"]', 2, 'Red marrow, which makes blood cells, is in spongy bone, ends of long bones, ribs, vertebrae, sternum and pelvis.', '{"0": "Yellow marrow fills long-bone shafts.", "1": "Cartilage has no marrow.", "3": "Not the location."}'),
  ('BIO-1476', 'Human physiology', 'Bone', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 257 (§12.1)', 'Yellow bone marrow consists mostly of', '["red blood cell precursors", "fat cells serving as an energy reserve", "osteoclasts", "chondrocytes"]', 1, 'Yellow marrow fills long-bone shafts, is mostly fat and can convert to red marrow after severe blood loss.', '{"0": "That is red marrow''s role.", "2": "Osteoclasts resorb bone.", "3": "Chondrocytes are in cartilage."}'),
  ('BIO-1477', 'Human physiology', 'Bone', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 257 (§12.1)', 'Bones make up what proportion of body mass?', '["About 50%", "About 35%", "Less than 20%", "More than 60%"]', 2, 'Despite their number and size, bones make up less than 20% of body mass.', '{"0": "Too high.", "1": "Too high.", "3": "Too high."}'),
  ('BIO-1478', 'Human physiology', 'Bone cells', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 257 (§12.1)', 'Osteoblasts become osteocytes when they', '["fuse with macrophages", "become surrounded by the matrix they secrete", "lose their nuclei", "move into cartilage"]', 1, 'Osteoblasts secrete unmineralized ground substance; once surrounded by matrix they become osteocytes.', '{"0": "Osteoclasts come from macrophages.", "2": "Not described.", "3": "Not described."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-1479', 'Human physiology', 'Bone cells', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 257 (§12.1)', 'Cells that break down bone and release calcium and phosphate into blood are', '["osteoblasts", "osteocytes", "chondrocytes", "osteoclasts"]', 3, 'Osteoclasts develop from macrophages and resorb bone, releasing calcium and phosphate.', '{"0": "Osteoblasts form bone.", "1": "Osteocytes maintain bone.", "2": "Chondrocytes maintain cartilage."}'),
  ('BIO-1480', 'Human physiology', 'Bone cells', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 257 (§12.1)', 'Which bone cells regulate calcium release from bone to blood while maintaining bone tissue?', '["Osteocytes", "Osteoblasts", "Chondrocytes", "Myofibres"]', 0, 'Mature osteocytes maintain bone by secreting enzymes and minerals and regulate calcium release to blood.', '{"1": "Osteoblasts form new bone.", "2": "Chondrocytes are in cartilage.", "3": "Myofibres are muscle cells."}'),
  ('BIO-1481', 'Human physiology', 'Bone development', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 257 (§12.1)', 'The replacement of cartilage by bone through mineral deposition is called', '["osteoporosis", "ossification", "remodelling only", "chondrification"]', 1, 'The step in which cartilage is replaced by bone by deposition of minerals is ossification.', '{"0": "Osteoporosis is bone loss.", "2": "Remodelling continues after bones form.", "3": "Not the term."}'),
  ('BIO-1482', 'Human physiology', 'Bone development', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 258 (§12.1)', 'Which bones develop directly into bone without a cartilage stage?', '["Femur", "Humerus", "Some bones of the skull", "Vertebrae"]', 2, 'Some skull bones form directly as flat bone plates without cartilage first.', '{"0": "The femur forms from cartilage.", "1": "The humerus forms from cartilage.", "3": "Not given as an example."}'),
  ('BIO-1483', 'Human physiology', 'Cartilage', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 258 (§12.1)', 'Cartilage heals very slowly because', '["its matrix has no blood vessels, so cells are supplied by diffusion", "it has too many osteoclasts", "it is covered by periosteum", "it is made of calcium crystals"]', 0, 'There are no blood vessels inside cartilage matrix; cells get supplies by diffusion, so repair is slow.', '{"1": "Osteoclasts are bone cells.", "2": "Cartilage has perichondrium.", "3": "Cartilage lacks calcium crystals."}'),
  ('BIO-1484', 'Human physiology', 'Cartilage', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 259 (§12.1)', 'Intervertebral discs and the pubic symphysis are made of', '["hyaline cartilage", "elastic cartilage", "compact bone", "fibrocartilage"]', 3, 'Fibrocartilage is in high-stress areas like intervertebral discs and the pubic symphysis.', '{"0": "Hyaline is in nose, trachea and joint surfaces.", "1": "Elastic is in ear and epiglottis.", "2": "These are cartilage."}'),
  ('BIO-1485', 'Human physiology', 'Cartilage', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 259 (§12.1)', 'The external ear and epiglottis contain', '["hyaline cartilage", "fibrocartilage", "spongy bone", "elastic cartilage"]', 3, 'Elastic cartilage is found in the external ear and epiglottis.', '{"0": "Hyaline is in nose and trachea.", "1": "Fibrocartilage is in discs.", "2": "Not bone."}'),
  ('BIO-1486', 'Human physiology', 'Cartilage', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 259 (§12.1)', 'The most common type of cartilage, found on articulating bone surfaces, is', '["elastic cartilage", "hyaline cartilage", "fibrocartilage", "calcified cartilage"]', 1, 'Hyaline cartilage is the most common and covers bone surfaces in joints, the nose and trachea.', '{"0": "Elastic is in ear and epiglottis.", "2": "Fibrocartilage is in discs.", "3": "Not a type listed."}'),
  ('BIO-1487', 'Human physiology', 'Skeleton', 'easy', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 259 (§12.1)', 'The adult human skeleton has', '["206 bones", "208 bones", "33 bones", "300 bones"]', 0, 'The human skeletal system consists of 206 bones, in axial and appendicular divisions.', '{"1": "Not the number.", "2": "33 is the vertebrae.", "3": "Not the adult number."}'),
  ('BIO-1488', 'Human physiology', 'Skeleton', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 260 (§12.1)', 'How many bones form the cranium?', '["Fourteen", "Twenty-two", "Eight", "Six"]', 2, 'The skull has 22 bones: 8 cranial and 14 facial.', '{"0": "Fourteen are facial.", "1": "Twenty-two is the whole skull.", "3": "Six are middle-ear ossicles."}'),
  ('BIO-1489', 'Human physiology', 'Skeleton', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 261 (§12.1)', 'The hyoid bone is unusual because it', '["is part of the cranium", "forms the wrist", "is a fused vertebra", "does not articulate with any other bone of the head"]', 3, 'The hyoid lies at the base of the skull below the tongue and does not articulate with any other head bone.', '{"0": "It is a neck bone.", "1": "Carpals form the wrist.", "2": "It is not a vertebra."}'),
  ('BIO-1490', 'Human physiology', 'Skeleton', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 261 (§12.1)', 'The first and second cervical vertebrae are the', '["sacrum and coccyx", "atlas and axis", "malleus and incus", "ilium and ischium"]', 1, 'Of the seven cervical vertebrae, the first is the atlas and the second the axis.', '{"0": "These are fused pelvic vertebrae.", "2": "These are ear ossicles.", "3": "These are hip bones."}'),
  ('BIO-1491', 'Human physiology', 'Skeleton', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 261 (§12.1)', 'The vertebral column has how many vertebrae?', '["12", "24", "26", "33"]', 3, 'There are 33 vertebrae: 7 cervical, 12 thoracic, 5 lumbar, 5 sacral and 4 coccygeal.', '{"0": "12 is the thoracic vertebrae.", "1": "24 is the number of ribs.", "2": "Not the book''s count."}'),
  ('BIO-1492', 'Human physiology', 'Skeleton', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 262 (§12.1)', 'Ribs 8, 9 and 10, which attach to the sternum by a common costal cartilage, are', '["false ribs", "true ribs", "floating ribs", "cervical ribs"]', 0, 'The first 7 pairs are true ribs; pairs 8–10 are false ribs; pairs 11–12 are floating ribs.', '{"1": "True ribs have separate cartilages.", "2": "Floating ribs do not reach the sternum.", "3": "Not described."}'),
  ('BIO-1493', 'Human physiology', 'Skeleton', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 262 (§12.1)', 'The pectoral girdle consists of', '["two hip bones", "the sternum and ribs", "a pair of clavicles and a pair of scapulae", "humerus and radius"]', 2, 'The pectoral girdle is two clavicles (collar bones) and two scapulae (shoulder bones).', '{"0": "Hip bones form the pelvic girdle.", "1": "These are axial bones.", "3": "These are limb bones."}'),
  ('BIO-1494', 'Human physiology', 'Skeleton', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 263 (§12.1)', 'Each hip bone is formed by the fusion of', '["femur, tibia and fibula", "sacrum and coccyx", "clavicle and scapula", "ilium, ischium and pubis"]', 3, 'Each hip bone contains the ilium, ischium and pubis, which meet at the acetabulum.', '{"0": "These are leg bones.", "1": "These are vertebrae.", "2": "These form the pectoral girdle."}'),
  ('BIO-1495', 'Human physiology', 'Skeleton', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 263 (§12.1)', 'The patella is', '["the shin bone", "a bone of the wrist", "embedded in a tendon running over the knee joint", "part of the pelvic girdle"]', 2, 'The patella (kneecap) lies embedded in a long tendon over the knee joint.', '{"0": "The tibia is the shin bone.", "1": "Carpals form the wrist.", "3": "Not part of the girdle."}'),
  ('BIO-1496', 'Human physiology', 'Joints', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 263 (§12.1)', 'Sutures of the skull are examples of', '["fibrous joints", "cartilaginous joints", "synovial joints", "hinge joints"]', 0, 'In fibrous joints bones are joined by collagen fibres and do not move; sutures are examples.', '{"1": "Cartilaginous joints allow slight movement.", "2": "Synovial joints move freely.", "3": "Hinge joints are synovial."}'),
  ('BIO-1497', 'Human physiology', 'Joints', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 264 (§12.1)', 'The joint between the first rib and the sternum is a', '["fibrous joint", "cartilaginous joint with hyaline cartilage", "synovial hinge joint", "ball-and-socket joint"]', 1, 'Some cartilaginous joints use hyaline cartilage, such as between the first rib and sternum.', '{"0": "Not fibrous.", "2": "Not synovial.", "3": "Not synovial."}'),
  ('BIO-1498', 'Human physiology', 'Joints', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 264 (§12.1)', 'Synovial fluid that lubricates a joint is secreted by the', '["articular cartilage", "ligaments", "periosteum", "synovial membrane lining the fibrous capsule"]', 3, 'The fibrous capsule has outer ligaments and an inner synovial membrane that secretes synovial fluid.', '{"0": "Articular cartilage provides a smooth surface.", "1": "Ligaments connect bones.", "2": "Periosteum covers bone."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-1499', 'Human physiology', 'Joints', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 264 (§12.1)', 'Which type of synovial joint is found between the first and second cervical vertebrae?', '["Hinge joint", "Pivot joint", "Saddle joint", "Ball-and-socket joint"]', 1, 'Pivot joints allow rotation around one axis, as between the first and second neck vertebrae.', '{"0": "Elbow and knee are hinge joints.", "2": "The thumb joint is saddle.", "3": "Shoulder and hip are ball-and-socket."}'),
  ('BIO-1500', 'Human physiology', 'Joints', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 264 (§12.1)', 'The thumb joint is a', '["pivot joint", "gliding joint", "saddle joint", "hinge joint"]', 2, 'Saddle joints allow movement in two planes because one surface is concave and the other convex, as in the thumb.', '{"0": "Pivot is between atlas and axis.", "1": "Gliding is between vertebrae and carpals.", "3": "Hinge is elbow and knee."}'),
  ('BIO-1501', 'Human physiology', 'Joints', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 264 (§12.1)', 'The joint of the wrist with the radius, which allows movement in two planes but no rotation, is', '["an ellipsoidal joint", "a ball-and-socket joint", "a pivot joint", "a fibrous joint"]', 0, 'Ellipsoidal joints allow two-plane movement without rotation, e.g. wrist with radius.', '{"1": "That allows all directions.", "2": "That allows rotation.", "3": "That allows no movement."}'),
  ('BIO-1502', 'Human physiology', 'Joints', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 265 (§12.1)', 'Which feature of the human skeleton helps bipedal posture?', '["A long, narrow pelvis", "An S-shaped curve of the vertebral column", "A straight femur angled outward", "Long, grasping toes"]', 1, 'The S-shaped spine, short broad pelvis, inward-angled femur, foot arch and short toes support bipedalism.', '{"0": "The human pelvis is short and broad.", "2": "The femur angles inward.", "3": "Human toes are short and less prehensile."}'),
  ('BIO-1503', 'Human physiology', 'Arthritis', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 267 (§12.2)', 'Osteoarthritis occurs when', '["articular cartilage gradually softens and disintegrates", "uric acid crystals form in joints", "the synovial membrane is attacked by the immune system", "bones lose calcium after menopause"]', 0, 'Osteoarthritis, the most common type, is gradual breakdown of articular cartilage in knees, hips and spine joints.', '{"1": "That is gout.", "2": "That is rheumatoid arthritis.", "3": "That is osteoporosis."}'),
  ('BIO-1504', 'Human physiology', 'Arthritis', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 267 (§12.2)', 'Rheumatoid arthritis is', '["caused by uric acid crystals", "wear of articular cartilage", "a bacterial infection", "an autoimmune disorder in which the synovial membrane is inflamed"]', 3, 'Rheumatoid arthritis results from autoimmune inflammation of the synovial membrane, usually in wrists and hands.', '{"0": "That is gout.", "1": "That is osteoarthritis.", "2": "Not the cause."}'),
  ('BIO-1505', 'Human physiology', 'Arthritis', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 268 (§12.2)', 'Gout most commonly affects the joint of the', '["shoulder", "hip", "big toe", "jaw"]', 2, 'Gouty arthritis from uric acid crystals most commonly affects the big toe joint.', '{"0": "Not the most common site.", "1": "Not the most common site.", "3": "Not the most common site."}'),
  ('BIO-1506', 'Human physiology', 'Skeletal disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 266 (§12.2)', 'A slipped (herniated) disc occurs when', '["a vertebra fractures", "the outer layer of an intervertebral disc tears and its gel-like core presses on nerves", "the sciatic nerve is cut", "bones lose density"]', 1, 'A tear in the disc''s outer layer lets the inner gel leak and press on nerves or the spinal cord.', '{"0": "Not described.", "2": "Sciatica is compression, not cutting.", "3": "That is osteoporosis."}'),
  ('BIO-1507', 'Human physiology', 'Skeletal disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 266 (§12.2)', 'Spondylosis is most common in the', '["thoracic and sacral regions", "skull", "pelvic girdle", "lumbar and cervical regions"]', 3, 'Spondylosis, degeneration of the vertebral column, is most common in the lower back and neck.', '{"0": "Not the most common regions.", "1": "Not part of the vertebral column.", "2": "Not part of the vertebral column."}'),
  ('BIO-1508', 'Human physiology', 'Skeletal disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 267 (§12.2)', 'Sciatica is often caused by', '["uric acid in the blood", "low blood calcium", "a herniated or bulging disc pressing on the sciatic nerve", "a sprained ankle"]', 2, 'Sciatica is compression or irritation of the sciatic nerve, often by a herniated or bulging disc.', '{"0": "That is gout.", "1": "That causes tetany.", "3": "Not the cause."}'),
  ('BIO-1509', 'Human physiology', 'Skeletal disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 268 (§12.2)', 'In women, osteoporosis accelerates after menopause because of', '["a drop in oestrogen levels", "a rise in uric acid", "excess vitamin D", "too much weight-bearing exercise"]', 0, 'Falling oestrogen after menopause accelerates bone loss.', '{"1": "Uric acid causes gout.", "2": "Vitamin D helps calcium absorption.", "3": "Lack of such exercise weakens bone."}'),
  ('BIO-1510', 'Human physiology', 'Joint injuries', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 269 (§12.2)', 'A sprain is an injury to', '["tendons only", "ligaments", "articular cartilage", "the bone shaft"]', 1, 'A sprain is stretching or tearing of ligaments when a joint is forced beyond its range.', '{"0": "Tendons join muscle to bone.", "2": "Not the definition.", "3": "Not the definition."}'),
  ('BIO-1511', 'Human physiology', 'Joint injuries', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 269 (§12.2)', 'First aid for a dislocation includes', '["immobilizing the area without trying to re-align the joint", "forcefully re-aligning the joint", "applying heat immediately", "lowering the limb below the heart"]', 0, 'Immobilize with a sling or splint, apply ice, elevate the limb and seek medical attention; do not re-align.', '{"1": "Re-aligning is to be avoided.", "2": "Ice is applied.", "3": "The limb is elevated."}'),
  ('BIO-1512', 'Human physiology', 'Muscle types', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 270 (§12.3)', 'Smooth muscle fibres are', '["cylindrical, multinucleate and striated", "branched with intercalated discs", "spindle-shaped, uninucleate and without striations", "found only in the heart"]', 2, 'Smooth muscle fibres are spindle-shaped with a single nucleus and no striations.', '{"0": "That is skeletal muscle.", "1": "That is cardiac muscle.", "3": "That is cardiac muscle."}'),
  ('BIO-1513', 'Human physiology', 'Muscle types', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 270 (§12.3)', 'Cardiac muscle fibres are', '["unstriated and spindle-shaped", "multinucleated and voluntary", "found in the stomach wall", "striated and branched, usually with one central nucleus"]', 3, 'Cardiac fibres branch extensively, are striated and usually have one central nucleus.', '{"0": "That is smooth muscle.", "1": "That is skeletal muscle.", "2": "Smooth muscle is in the stomach wall."}'),
  ('BIO-1514', 'Human physiology', 'Muscle ultrastructure', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 271 (§12.3)', 'The plasma membrane of a skeletal muscle fibre is the', '["sarcolemma", "sarcoplasm", "sarcoplasmic reticulum", "perichondrium"]', 0, 'Each muscle fibre is enclosed by the sarcolemma; its cytoplasm is sarcoplasm.', '{"1": "Sarcoplasm is the cytoplasm.", "2": "SR stores calcium.", "3": "Perichondrium covers cartilage."}'),
  ('BIO-1515', 'Human physiology', 'Muscle ultrastructure', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 271 (§12.3)', 'T-tubules are', '["filaments of actin", "inward extensions of the sarcolemma that reach the sarcoplasmic reticulum", "bands of myosin", "connective tissue around muscles"]', 1, 'The sarcolemma penetrates the fibre to form transverse tubules, which reach the ends of the SR.', '{"0": "Actin forms thin filaments.", "2": "Myosin forms thick filaments.", "3": "Not T-tubules."}'),
  ('BIO-1516', 'Human physiology', 'Muscle ultrastructure', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 271 (§12.3)', 'The dark A-bands of skeletal muscle are formed by', '["thin actin filaments only", "Z-lines", "T-tubules", "thick myosin filaments"]', 3, 'Thick myosin filaments make the dark A-bands; thin actin filaments make the light I-bands.', '{"0": "Actin alone forms I-bands.", "1": "Z-lines bound the sarcomere.", "2": "Not bands."}'),
  ('BIO-1517', 'Human physiology', 'Muscle ultrastructure', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 272 (§12.3)', 'The H-band is the region of the A-band where', '["actin attaches to the Z-line", "only thin filaments are present", "there is no overlap of thin and thick filaments", "calcium is stored"]', 2, 'The lighter H-band in the centre of the A-band is where no overlap of actin and myosin occurs.', '{"0": "That is the Z-line.", "1": "That describes the I-band.", "3": "Calcium is stored in SR."}'),
  ('BIO-1518', 'Human physiology', 'Muscle ultrastructure', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 272 (§12.3)', 'The dark line in the centre of the H-band that stabilizes thick filaments is the', '["M-line", "Z-line", "A-band", "I-band"]', 0, 'The centre of the H-band may show a dark M-line that stabilizes the thick filaments.', '{"1": "Z-lines bound the sarcomere.", "2": "The A-band contains the H-band.", "3": "I-bands are light bands."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-1519', 'Human physiology', 'Muscle ultrastructure', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 273 (§12.3)', 'The diameters of thick and thin myofilaments are about', '["7–8 nm and 16 nm", "1 µm and 0.5 µm", "8 µm and 16 µm", "16 nm and 7–8 nm"]', 3, 'Thick myosin filaments are about 16 nm and thin filaments 7–8 nm in diameter.', '{"0": "Reversed.", "1": "Far too large.", "2": "Far too large."}'),
  ('BIO-1520', 'Human physiology', 'Muscle ultrastructure', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 273 (§12.3)', 'In relaxed muscle, the myosin-binding sites on actin are blocked by', '["troponin''s calcium-binding subunit", "ATP", "tropomyosin", "the Z-line"]', 2, 'Two strands of tropomyosin wrap the actin core and block myosin-binding sites in relaxed muscle.', '{"0": "Troponin holds tropomyosin in place.", "1": "ATP binds myosin heads.", "3": "The Z-line anchors actin."}'),
  ('BIO-1521', 'Human physiology', 'Muscle ultrastructure', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 273 (§12.3)', 'Troponin consists of three polypeptides that bind respectively to', '["myosin, ATP and actin", "actin, tropomyosin and calcium ions", "calcium, ATP and myosin", "Z-line, M-line and actin"]', 1, 'One troponin polypeptide is inhibitory and binds actin, one binds tropomyosin and one binds Ca2+.', '{"0": "Not its partners.", "2": "Not its partners.", "3": "Not its partners."}'),
  ('BIO-1522', 'Human physiology', 'Muscle contraction', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 273 (§12.3)', 'The neurotransmitter released at the motor neuron–muscle synapse is', '["adrenaline", "dopamine", "acetylcholine", "histamine"]', 2, 'When a nerve impulse arrives, the motor neuron releases acetylcholine at the synapse.', '{"0": "Not named here.", "1": "Not named here.", "3": "Histamine dilates capillaries."}'),
  ('BIO-1523', 'Human physiology', 'Muscle contraction', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 274 (§12.3)', 'Calcium ions start contraction by binding to', '["troponin, which shifts tropomyosin off the binding sites on actin", "myosin heads directly", "ATP", "the sarcolemma"]', 0, 'Released Ca2+ binds troponin, which moves tropomyosin away from myosin-binding sites on actin.', '{"1": "Myosin binds actin after sites open.", "2": "Not described.", "3": "Ca2+ comes from the SR into the cytosol."}'),
  ('BIO-1524', 'Human physiology', 'Muscle contraction', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 274 (§12.3)', 'During the power stroke, myosin heads', '["bind ATP and detach from actin", "hydrolyse calcium", "push actin away from the centre", "release ADP and Pi and bend, pulling actin toward the sarcomere centre"]', 3, 'After forming cross-bridges, myosin heads release ADP and Pi and bend, pulling actin toward the centre.', '{"0": "That ends the cycle.", "1": "Calcium is not hydrolysed.", "2": "Muscles pull."}'),
  ('BIO-1525', 'Human physiology', 'Muscle contraction', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 274 (§12.3)', 'During contraction, the A-bands', '["shorten to half", "move closer together but do not shorten", "disappear", "lengthen"]', 1, 'Z-lines move closer, the H-zone disappears, and adjacent A-bands come closer without shortening.', '{"0": "A-bands keep their length.", "2": "The H-zone disappears.", "3": "Not lengthened."}'),
  ('BIO-1526', 'Human physiology', 'Muscle contraction', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 275 (§12.3)', 'Rigor mortis occurs because after death', '["no ATP is produced, so myosin heads cannot detach from actin", "calcium cannot reach troponin", "tropomyosin blocks all sites", "actin filaments dissolve"]', 0, 'Without ATP, cross-bridges cannot break, causing the stiffness of death.', '{"1": "Calcium is not the reason given.", "2": "That would relax muscle.", "3": "Not described."}'),
  ('BIO-1527', 'Human physiology', 'Muscle arrangement', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 275 (§12.3)', 'The end of a muscle attached to the bone that moves is the', '["origin", "belly", "tendon sheath", "insertion"]', 3, 'The origin is on the stationary bone, the insertion on the moving bone, and the belly in between.', '{"0": "The origin stays still.", "1": "The belly is the middle.", "2": "Not the term."}'),
  ('BIO-1528', 'Human physiology', 'Muscle arrangement', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 275 (§12.3)', 'Flexion of the lower leg at the knee is done by the', '["quadriceps", "biceps", "hamstrings", "triceps"]', 2, 'The hamstrings, three muscles at the back of the thigh, flex the knee; the quadriceps extend it.', '{"0": "Quadriceps straighten the leg.", "1": "Biceps flex the elbow.", "3": "Triceps extend the elbow."}'),
  ('BIO-1529', 'Human physiology', 'Muscle arrangement', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 276 (§12.3)', 'The quadriceps are inserted on the', '["upper fibula and tibia", "patella and tibia", "femur only", "pelvic girdle"]', 1, 'Quadriceps originate on the ilium and femur and insert on the patella and tibia.', '{"0": "That is the hamstring insertion.", "2": "The femur is an origin.", "3": "The pelvic girdle is an origin."}'),
  ('BIO-1530', 'Human physiology', 'Muscle arrangement', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 277 (§12.3)', 'In the skeleton as a lever system, joints act as', '["loads", "efforts", "fulcrums", "rods"]', 2, 'Bones are the rods, joints the fulcrums, muscles provide the effort and the weight is the load.', '{"0": "The load is the weight moved.", "1": "Muscles provide effort.", "3": "Bones are rods."}'),
  ('BIO-1531', 'Human physiology', 'Muscle disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 276 (§12.3)', 'Which factor contributes to muscle fatigue?', '["Excess ATP in muscle", "High blood calcium", "Too many mitochondria", "Build-up of lactate and hydrogen ions"]', 3, 'Muscle fatigue results from ATP depletion, metabolic wastes like lactate and H+, poor Ca2+ handling and fibre damage.', '{"0": "ATP depletion, not excess, contributes.", "1": "Not a cause listed.", "2": "Not a cause listed."}'),
  ('BIO-1532', 'Human physiology', 'Muscle disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 276 (§12.3)', 'The most common cause of tetany is', '["Clostridium tetani infection", "low blood calcium (hypocalcaemia)", "excess uric acid", "dehydration only"]', 1, 'Tetany is most often due to hypocalcaemia, from vitamin D deficiency, renal failure or thyroid disorders.', '{"0": "That causes tetanus.", "2": "That causes gout.", "3": "Dehydration is a cause of cramps."}'),
  ('BIO-1533', 'Human physiology', 'Muscle disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 277 (§12.3)', 'Tetanus differs from tetany in that tetanus is', '["a bacterial infection whose toxin mainly stiffens jaw and neck muscles", "caused by low blood calcium", "a mild condition", "a disorder of cartilage"]', 0, 'Tetanus is a severe infection by Clostridium tetani whose toxin causes stiffness, mainly of jaw and neck muscles.', '{"1": "That is tetany.", "2": "Tetanus is more serious.", "3": "Not a cartilage disorder."}'),
  ('BIO-1534', 'Human physiology', 'Muscle disorders', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human Skeletal and Muscular Systems, p. 276 (§12.3)', 'Muscle cramps can be relieved by', '["gently stretching and massaging the affected muscle", "immobilizing the muscle for weeks", "calcium injections only", "removing the tendon"]', 0, 'Gentle stretching and massage, heat or cold and pain relievers help relieve cramps.', '{"1": "Not advised.", "2": "Supplements treat tetany from low calcium.", "3": "Not a treatment."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

